.snake::after.background:
conic-gradient(
      from var(--snake-angle),
      transparent 0deg,
      transparent 214deg,
      color-mix(in oklch, var(--brand) 18%, transparent) 300deg,
      var(--brand) 350deg,
      transparent 360deg
    )

.shimmer.background-image:
linear-gradient(
      100deg,
      var(--muted-foreground) 34%,
      color-mix(in oklch, var(--foreground) 78%, var(--brand)) 50%,
      var(--muted-foreground) 66%
    )
